-- Halk hareketleri: tüm parasal işlemler atomik; genel kilit -> kaynak -> eylem.
create table if not exists oyun.sokak_eylem_ayar(id integer primary key default 1 check(id=1),aktif boolean not null default false,baslatma_bedeli numeric not null default 50000,il_cooldown_saat integer not null default 168,parti_cooldown_saat integer not null default 72,max_sure_saat integer not null default 120,sakinlestirme_carpani numeric not null default 3,kirmizi_esik numeric not null default 75,il_es_zamanli_ust_sinir integer not null default 1,ulke_es_zamanli_ust_sinir integer not null default 6,orgut_es_zamanli_destek_siniri integer not null default 3);
insert into oyun.sokak_eylem_ayar(id) values(1) on conflict do nothing;
create table if not exists oyun.sokak_eylem(id bigint generated by default as identity primary key,il_id smallint not null references oyun.iller,parti_id bigint not null references oyun.partiler,baslatan uuid not null references oyun.profiller,gerekce text not null,durum text not null default 'aktif',baslangic timestamptz not null default now(),bitis timestamptz not null,muhalefet_fonu numeric not null default 0,iktidar_fonu numeric not null default 0,kirmizi_baslangic timestamptz,erken_secim_uyarisi boolean not null default false);
create table if not exists oyun.sokak_eylem_fon(id bigint generated by default as identity primary key,eylem_id bigint not null references oyun.sokak_eylem,oyuncu_id uuid not null references oyun.profiller,taraf text not null,tutar numeric not null check(tutar>0),zaman timestamptz not null default now());
create table if not exists oyun.sokak_eylem_destek(id bigint generated by default as identity primary key,eylem_id bigint not null references oyun.sokak_eylem,destekci_tur text not null,destekci_id text not null,taraf text not null,temsilci uuid not null references oyun.profiller,destek_turu text not null default 'katilim',tutar numeric not null default 0,zaman timestamptz not null default now(),unique(eylem_id,destekci_tur,destekci_id,taraf,destek_turu));
alter table oyun.sokak_eylem add column if not exists seviye numeric not null default 0;
alter table oyun.sokak_eylem add column if not exists son_etki timestamptz;
alter table oyun.sokak_eylem add column if not exists kapandi timestamptz;
alter table oyun.sokak_eylem add column if not exists hukumet_yaniti text;
alter table oyun.sokak_eylem add column if not exists yanit_zamani timestamptz;
alter table oyun.sokak_eylem_fon add column if not exists kaynak_tur text not null default 'parti';
alter table oyun.sokak_eylem_fon add column if not exists kaynak_id text;
create table if not exists oyun.sokak_kriz(id integer primary key check(id=1),kirmizi_baslangic timestamptz,son_secim timestamptz,son_etki timestamptz,secim_donem text);
insert into oyun.sokak_kriz(id) values(1) on conflict do nothing;
create index if not exists sokak_il_zaman on oyun.sokak_eylem(il_id,baslangic desc);
create index if not exists sokak_parti_zaman on oyun.sokak_eylem(parti_id,baslangic desc);
create index if not exists sokak_fon_kaynak on oyun.sokak_eylem_fon(kaynak_tur,kaynak_id,zaman);
create index if not exists sokak_fon_eylem on oyun.sokak_eylem_fon(eylem_id);
create index if not exists sokak_destek_kaynak on oyun.sokak_eylem_destek(destekci_tur,destekci_id);

create or replace function oyun.sokak_iktidar(p_user uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from oyun.makamlar m where m.user_id=p_user and m.bit is null and m.tur in ('cb','bakan','cb_yardimcisi')) or exists(select 1 from oyun.profiller p join oyun.profiller cb on cb.parti_id=p.parti_id join oyun.makamlar m on m.user_id=cb.id and m.bit is null and m.tur in ('cb','bakan') where p.id=p_user and p.parti_id is not null)
$$;
create or replace function oyun.sokak_memnuniyetsizlik(p_il integer) returns numeric language sql stable set search_path='' as $$
 select round(least(100,greatest(0,(100-u.memnuniyet)*0.35+(100-coalesce(i.memnuniyet,50))*0.45+greatest(0,u.issizlik-5)*2+greatest(0,u.enflasyon-20)*0.35+greatest(0,u.vergi-20))),1) from oyun.ulke u left join oyun.il_durum i on i.il_id=p_il where u.id=1
$$;
create or replace function oyun.sokak_duyur(p_id bigint,p_metin text) returns void language plpgsql set search_path='' as $$
declare x oyun.sokak_eylem;
begin
 select * into x from oyun.sokak_eylem where id=p_id;
 perform oyun.olay('siyaset',p_metin,x.il_id,x.parti_id);
 insert into oyun.bildirimler(user_id,zaman,metin) select distinct p.id,oyun.simdi(),p_metin from oyun.profiller p where not p.yasakli and (p.id=x.baslatan or exists(select 1 from oyun.sokak_eylem_destek d where d.eylem_id=x.id and d.temsilci=p.id) or exists(select 1 from oyun.makamlar m where m.user_id=p.id and m.bit is null and m.tur in ('cb','bakan','cb_yardimcisi')));
end $$;
create or replace function oyun.sokak_yenile(p_id bigint) returns void language plpgsql set search_path='' as $$
declare x oyun.sokak_eylem; a oyun.sokak_eylem_ayar; t timestamptz:=oyun.simdi(); n integer; yerel integer; puan numeric; kirmizi boolean;
begin
 select * into a from oyun.sokak_eylem_ayar where id=1;
 select * into x from oyun.sokak_eylem where id=p_id for update;
 if x.id is null or x.durum<>'aktif' then return; end if;
 if x.bitis<=t then
  update oyun.sokak_eylem set durum='bitti',kapandi=t,kirmizi_baslangic=null,seviye=0 where id=x.id;
  perform oyun.sokak_duyur(x.id,'Eylem #'||x.id||' süresi doldu. İl dinlenme süresine girdi.'); return;
 end if;
 if x.iktidar_fonu>=x.muhalefet_fonu*a.sakinlestirme_carpani then
  update oyun.sokak_eylem set durum='yatisti',kapandi=t,kirmizi_baslangic=null,seviye=0 where id=x.id;
  perform oyun.sokak_duyur(x.id,'Eylem #'||x.id||' uzlaşma fonuyla yatıştı.'); return;
 end if;
 select count(*) into n from oyun.sokak_eylem_destek d join oyun.profiller p on p.id=d.temsilci where d.eylem_id=x.id and d.destekci_tur='oyuncu' and d.destek_turu='katilim' and d.taraf='muhalefet' and p.il_id=x.il_id and p.il_at<t-interval '3 days' and not p.yasakli and p.olusturma<t-interval '3 days' and p.son_gorulme>t-interval '14 days';
 select count(*) into yerel from oyun.profiller where il_id=x.il_id and not yasakli and olusturma<t-interval '3 days' and son_gorulme>t-interval '14 days';
 puan:=least(100,greatest(0,oyun.sokak_memnuniyetsizlik(x.il_id)*0.5+least(30,x.muhalefet_fonu/a.baslatma_bedeli*5)+least(30,n*3)-30*x.iktidar_fonu/greatest(1,x.muhalefet_fonu*a.sakinlestirme_carpani)));
 kirmizi:=puan>=a.kirmizi_esik and n>=greatest(5,ceil(yerel*0.30)) and oyun.sokak_memnuniyetsizlik(x.il_id)>=40;
 if not kirmizi then puan:=least(puan,a.kirmizi_esik-1); end if;
 update oyun.sokak_eylem set seviye=puan,kirmizi_baslangic=case when kirmizi then coalesce(kirmizi_baslangic,t) else null end where id=x.id;
 if kirmizi and x.kirmizi_baslangic is null then perform oyun.sokak_duyur(x.id,'Eylem #'||x.id||' kırmızı seviyeye ulaştı. Hükümetin yanıtı bekleniyor.');
 elsif not kirmizi and x.kirmizi_baslangic is not null then perform oyun.sokak_duyur(x.id,'Eylem #'||x.id||' kırmızı seviyeden çıktı; kesintisiz kriz sayacı sıfırlandı.'); end if;
end $$;

create or replace function public.sokak_eylem_baslat(p_il integer,p_gerekce text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); p oyun.profiller; pa oyun.partiler; a oyun.sokak_eylem_ayar; t timestamptz:=oyun.simdi(); eid bigint; n integer;
begin
 if u is null then raise exception 'Oturum gerekli'; end if;
 perform pg_advisory_xact_lock(781231,1);
 p:=oyun.profilim();
 if p.yasakli or p.olusturma>t-interval '7 days' then raise exception 'Kısıtsız ve en az 7 günlük hesap gerekli'; end if;
 select * into a from oyun.sokak_eylem_ayar where id=1;
 if not a.aktif then raise exception 'Sokak hareketleri kapalı'; end if;
 if p_il is null or p_il not between 1 and 81 then raise exception 'Geçersiz il'; end if;
 if length(btrim(coalesce(p_gerekce,''))) not between 15 and 400 then raise exception 'Gerekçe 15–400 karakter olmalı'; end if;
 select * into pa from oyun.partiler where id=p.parti_id for update;
 if pa.id is null or pa.kapali or pa.gb is distinct from u or oyun.sokak_iktidar(u) then raise exception 'Yalnız muhalefet partisi genel başkanı başlatabilir'; end if;
 if oyun.sokak_memnuniyetsizlik(p_il)<35 then raise exception 'İlde memnuniyetsizlik en az 35/100 olmalı'; end if;
 select count(*) into n from oyun.profiller where il_id=p_il and not yasakli and olusturma<t-interval '3 days' and son_gorulme>t-interval '14 days';
 if n<3 then raise exception 'İlde en az 3 kıdemli aktif oyuncu gerekli'; end if;
 if exists(select 1 from oyun.sokak_eylem where il_id=p_il and (durum='aktif' and bitis>t or coalesce(kapandi,bitis)>t-make_interval(hours=>a.il_cooldown_saat))) then raise exception 'İlde eylem var veya kapanıştan sonraki 7 günlük bekleme sürüyor'; end if;
 if exists(select 1 from oyun.sokak_eylem where parti_id=pa.id and (baslangic>t-make_interval(hours=>a.parti_cooldown_saat) or durum='aktif' and bitis>t)) then raise exception 'Partinin aktif eylemi var veya 72 saatlik bekleme sürüyor'; end if;
 if (select count(*) from oyun.sokak_eylem where durum='aktif' and bitis>t)>=a.ulke_es_zamanli_ust_sinir then raise exception 'Ülkede eşzamanlı eylem sınırına ulaşıldı'; end if;
 if exists(select 1 from oyun.sokak_kriz where son_secim>t-interval '7 days') then raise exception 'Seçim sonrası 7 günlük istikrar süresi devam ediyor'; end if;
 update oyun.partiler set kasa=kasa-a.baslatma_bedeli where id=pa.id and kasa>=a.baslatma_bedeli;
 if not found then raise exception 'Parti kasası yetersiz'; end if;
 insert into oyun.sokak_eylem(il_id,parti_id,baslatan,gerekce,baslangic,bitis,muhalefet_fonu,son_etki) values(p_il,pa.id,u,btrim(p_gerekce),t,t+interval '24 hours',a.baslatma_bedeli,t) returning id into eid;
 insert into oyun.parti_hareket(parti_id,zaman,tutar,aciklama,tur) values(pa.id,t,-a.baslatma_bedeli,'Halk hareketi #'||eid,'gider');
 insert into oyun.sokak_eylem_fon(eylem_id,oyuncu_id,taraf,tutar,zaman,kaynak_tur,kaynak_id) values(eid,u,'muhalefet',a.baslatma_bedeli,t,'parti',pa.id::text);
 insert into oyun.sokak_eylem_destek(eylem_id,destekci_tur,destekci_id,taraf,temsilci,destek_turu,tutar) values(eid,'parti',pa.id::text,'muhalefet',u,'fon',a.baslatma_bedeli);
 perform oyun.sokak_yenile(eid);
 perform oyun.sokak_duyur(eid,pa.ad||' il '||p_il||' için barışçıl eylem #'||eid||' başlattı: '||btrim(p_gerekce));
 return jsonb_build_object('tamam',true,'eylem_id',eid);
end $$;

create or replace function public.sokak_destek(p_eylem bigint,p_taraf text,p_kaynak text default 'oyuncu',p_kaynak_id bigint default null,p_tutar numeric default 0) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); p oyun.profiller; x oyun.sokak_eylem; a oyun.sokak_eylem_ayar; t timestamptz:=oyun.simdi(); kid text; toplam numeric; limit_tutar numeric;
begin
 if u is null then raise exception 'Oturum gerekli'; end if;
 perform pg_advisory_xact_lock(781231,1);
 p:=oyun.profilim();
 if p.yasakli or p.olusturma>t-interval '3 days' then raise exception 'Kısıtsız ve en az 3 günlük hesap gerekli'; end if;
 select * into a from oyun.sokak_eylem_ayar where id=1;
 if not a.aktif then raise exception 'Sokak hareketleri kapalı'; end if;
 if p_taraf is null or p_taraf not in ('muhalefet','iktidar') or p_kaynak is null or p_kaynak not in ('oyuncu','parti','dernek') or p_tutar is null or p_tutar::text in ('NaN','Infinity','-Infinity') or p_tutar<0 or p_tutar<>round(p_tutar,2) then raise exception 'Geçersiz destek'; end if;
 kid:=case when p_kaynak='oyuncu' then u::text else p_kaynak_id::text end;
 if p_kaynak='parti' and not exists(select 1 from oyun.partiler where id=p_kaynak_id and gb=u and not kapali) then raise exception 'Parti kasası için genel başkan yetkisi gerekli'; end if;
 if p_kaynak='dernek' and not exists(select 1 from oyun.dernekler where id=p_kaynak_id and baskan=u and not kapali) then raise exception 'Dernek başkanı yetkisi gerekli'; end if;
 if p_taraf='muhalefet' and oyun.sokak_iktidar(u) then raise exception 'İktidar üyeleri uzlaşma tarafını destekleyebilir'; end if;
 if p_tutar=0 and p_kaynak<>'oyuncu' then raise exception 'Kurumsal destek fonla verilir'; end if;
 select * into x from oyun.sokak_eylem where id=p_eylem for update;
 if x.id is null or x.durum<>'aktif' or x.bitis<=t then raise exception 'Eylem aktif değil'; end if;
 if exists(select 1 from oyun.sokak_eylem_destek where eylem_id=x.id and destekci_tur=p_kaynak and destekci_id=kid and taraf<>p_taraf) then raise exception 'Aynı eylemde iki taraf desteklenemez'; end if;
 if not exists(select 1 from oyun.sokak_eylem_destek where eylem_id=x.id and destekci_tur=p_kaynak and destekci_id=kid) and (select count(distinct d.eylem_id) from oyun.sokak_eylem_destek d join oyun.sokak_eylem e on e.id=d.eylem_id where d.destekci_tur=p_kaynak and d.destekci_id=kid and e.durum='aktif' and e.bitis>t)>=a.orgut_es_zamanli_destek_siniri then raise exception 'Aynı anda en fazla 3 eylem desteklenebilir'; end if;
 if p_tutar=0 then
  if p.il_id<>x.il_id or p.il_at>t-interval '3 days' then raise exception 'Katılım için ilde en az 3 günlük ikamet gerekir'; end if;
  insert into oyun.sokak_eylem_destek(eylem_id,destekci_tur,destekci_id,taraf,temsilci) values(x.id,'oyuncu',kid,p_taraf,u) on conflict do nothing;
 else
  if p_tutar<1000 then raise exception 'En az 1.000 TL fonlanabilir'; end if;
  limit_tutar:=a.baslatma_bedeli*(case when p_kaynak='oyuncu' then 2 else 5 end)*(case when p_taraf='iktidar' then 3 else 1 end);
  select coalesce(sum(tutar),0) into toplam from oyun.sokak_eylem_fon where kaynak_tur=p_kaynak and kaynak_id=kid and zaman>t-interval '24 hours';
  if toplam+p_tutar>limit_tutar then raise exception 'Kaynağın son 24 saatlik fon limiti aşılıyor: % TL',limit_tutar; end if;
  if p_taraf='muhalefet' and x.muhalefet_fonu+p_tutar>a.baslatma_bedeli*20 then raise exception 'Eylem toplam fon tavanına ulaşıyor'; end if;
  if p_taraf='iktidar' and x.iktidar_fonu+p_tutar>x.muhalefet_fonu*a.sakinlestirme_carpani then raise exception 'Gerekli uzlaşma tutarı: % TL',x.muhalefet_fonu*a.sakinlestirme_carpani-x.iktidar_fonu; end if;
  if p_kaynak='oyuncu' then
   update oyun.cuzdan set para=para-p_tutar where user_id=u and para>=p_tutar;
  elsif p_kaynak='parti' then
   update oyun.partiler set kasa=kasa-p_tutar where id=p_kaynak_id and kasa>=p_tutar;
  else update oyun.dernekler set kasa=kasa-p_tutar where id=p_kaynak_id and kasa>=p_tutar;
  end if;
  if not found then raise exception 'Bakiye yetersiz'; end if;
  if p_kaynak='oyuncu' then insert into oyun.hesap_hareket(user_id,zaman,tutar,tur,aciklama) values(u,t,-p_tutar,'gider','Halk hareketi #'||x.id||' / '||p_taraf);
  elsif p_kaynak='parti' then insert into oyun.parti_hareket(parti_id,zaman,tutar,tur,aciklama) values(p_kaynak_id,t,-p_tutar,'gider','Halk hareketi #'||x.id||' / '||p_taraf);
  else insert into oyun.dernek_hareket(dernek_id,zaman,tutar,tur,aciklama,user_id) values(p_kaynak_id,t,-p_tutar,'gider','Halk hareketi #'||x.id||' / '||p_taraf,u); end if;
  insert into oyun.sokak_eylem_fon(eylem_id,oyuncu_id,taraf,tutar,zaman,kaynak_tur,kaynak_id) values(x.id,u,p_taraf,p_tutar,t,p_kaynak,kid);
  insert into oyun.sokak_eylem_destek(eylem_id,destekci_tur,destekci_id,taraf,temsilci,destek_turu,tutar) values(x.id,p_kaynak,kid,p_taraf,u,'fon',p_tutar) on conflict(eylem_id,destekci_tur,destekci_id,taraf,destek_turu) do update set tutar=oyun.sokak_eylem_destek.tutar+excluded.tutar;
  update oyun.sokak_eylem set muhalefet_fonu=muhalefet_fonu+case when p_taraf='muhalefet' then p_tutar else 0 end,iktidar_fonu=iktidar_fonu+case when p_taraf='iktidar' then p_tutar else 0 end,bitis=case when p_taraf='muhalefet' then least(baslangic+make_interval(hours=>a.max_sure_saat),bitis+interval '12 hours'*(p_tutar/a.baslatma_bedeli)) else bitis end where id=x.id;
  perform oyun.olay('siyaset',format('Eylem #%s: %s tarafına %s TL %s desteği.',x.id,p_taraf,p_tutar,p_kaynak),x.il_id,x.parti_id);
 end if;
 perform oyun.sokak_yenile(x.id);
 -- Bir eylem kırmızıdan çıkınca ulusal 72 saatlik sayaç da anında kesilir.
 if (select count(*) from oyun.sokak_eylem where durum='aktif' and bitis>t and kirmizi_baslangic is not null)<3 then update oyun.sokak_kriz set kirmizi_baslangic=null where id=1; end if;
 return jsonb_build_object('tamam',true);
end $$;
create or replace function public.sokak_yanit(p_eylem bigint,p_metin text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); p oyun.profiller; x oyun.sokak_eylem;
begin
 if u is null then raise exception 'Oturum gerekli'; end if;
 perform pg_advisory_xact_lock(781231,1); p:=oyun.profilim();
 if p.yasakli or not exists(select 1 from oyun.makamlar where user_id=u and bit is null and tur in ('cb','bakan','cb_yardimcisi')) then raise exception 'Hükümet yetkisi gerekli'; end if;
 if length(btrim(coalesce(p_metin,''))) not between 20 and 500 then raise exception 'Yanıt 20–500 karakter olmalı'; end if;
 select * into x from oyun.sokak_eylem where id=p_eylem for update;
 if x.id is null or x.durum<>'aktif' or x.bitis<=oyun.simdi() then raise exception 'Eylem aktif değil'; end if;
 if x.yanit_zamani>oyun.simdi()-interval '6 hours' then raise exception 'Yanıtlar arasında 6 saat beklenmeli'; end if;
 update oyun.sokak_eylem set hukumet_yaniti=btrim(p_metin),yanit_zamani=oyun.simdi() where id=x.id;
 perform oyun.sokak_duyur(x.id,'Hükümet eylem #'||x.id||' taleplerine yanıt verdi: '||btrim(p_metin));
 return jsonb_build_object('tamam',true);
end $$;

create or replace function oyun.sokak_tick() returns void language plpgsql security definer set search_path='' as $$
declare t timestamptz:=oyun.simdi(); x record; k oyun.sokak_kriz; a oyun.sokak_eylem_ayar; n integer; kisi integer; aktif integer; dm text;
begin
 if not pg_try_advisory_xact_lock(781231,1) then return; end if;
 select * into a from oyun.sokak_eylem_ayar where id=1;
 if not a.aktif then return; end if;
 for x in select id from oyun.sokak_eylem where durum='aktif' order by id loop perform oyun.sokak_yenile(x.id); end loop;
 select count(*) into n from oyun.sokak_eylem where durum='aktif' and kirmizi_baslangic is not null and bitis>t;
 select * into k from oyun.sokak_kriz where id=1 for update;
 -- Etki zaman başına bir kere, tüm ülke için sınırlandırılır. Kesinti sonrası geçmiş günler topluca işlenmez.
 if n>0 and (k.son_etki is null or k.son_etki<=t-interval '24 hours') then
  update oyun.ulke set memnuniyet=greatest(0,memnuniyet-least(2,n*0.3)),buyume=greatest(-20,buyume-least(0.6,n*0.1)),enflasyon=least(200,enflasyon+least(0.3,n*0.05)) where id=1;
  update oyun.sokak_kriz set son_etki=t where id=1;
  perform oyun.olay('ekonomi',format('%s ilde kırmızı protesto: büyüme ve hükümet memnuniyeti geriledi; piyasalarda belirsizlik arttı.',n));
 end if;
 select count(distinct d.temsilci) into kisi from oyun.sokak_eylem_destek d join oyun.sokak_eylem e on e.id=d.eylem_id join oyun.profiller p on p.id=d.temsilci where e.durum='aktif' and e.kirmizi_baslangic is not null and e.bitis>t and d.destekci_tur='oyuncu' and d.destek_turu='katilim' and d.taraf='muhalefet' and not p.yasakli and p.il_id=e.il_id and p.il_at<t-interval '3 days' and p.son_gorulme>t-interval '14 days';
 select count(*) into aktif from oyun.profiller where not yasakli and olusturma<t-interval '3 days' and son_gorulme>t-interval '14 days';
 if n>=3 and kisi>=greatest(15,ceil(aktif*0.20)) then
  update oyun.sokak_kriz set kirmizi_baslangic=coalesce(kirmizi_baslangic,t) where id=1 returning * into k;
 else update oyun.sokak_kriz set kirmizi_baslangic=null where id=1; return; end if;
 if k.kirmizi_baslangic<=t-interval '72 hours' and (k.son_secim is null or k.son_secim<t-interval '14 days') and not exists(select 1 from oyun.secimler where tur in ('mv','cb','cb2') and (oy_bas<=t and (goreve_bas>t or durum<>'tamam') or durum='bekliyor' and oy_bas>t and oy_bas<t+interval '7 days')) and not exists(select 1 from oyun.makamlar where tur='cb' and bit is null and bas>t-interval '7 days') then
  dm:=oyun.erken_genel_secim_olustur(t,0::bigint);
  update oyun.sokak_kriz set son_secim=t,secim_donem=dm,kirmizi_baslangic=null where id=1;
  for x in select id from oyun.sokak_eylem where durum='aktif' loop
   update oyun.sokak_eylem set durum='bitti',kapandi=t,kirmizi_baslangic=null,erken_secim_uyarisi=true where id=x.id;
   perform oyun.sokak_duyur(x.id,'72 saatlik ulusal kriz koşulları sağlandı: erken seçim takvimi devreye girdi. Mevcut yönetim devir gününe kadar görevde.');
  end loop;
 end if;
end $$;

create or replace function public.sokak_eylemler() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); p oyun.profiller; t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli'; end if;
 p:=oyun.profilim();
 return jsonb_build_object('aktif',(select aktif from oyun.sokak_eylem_ayar where id=1),'ayar',(select to_jsonb(a) from oyun.sokak_eylem_ayar a),'iktidar',oyun.sokak_iktidar(u),'hukumet',exists(select 1 from oyun.makamlar where user_id=u and bit is null and tur in ('cb','bakan','cb_yardimcisi')),'baslatabilir',exists(select 1 from oyun.partiler where gb=u and not kapali) and not oyun.sokak_iktidar(u),'kriz',(select to_jsonb(k) from oyun.sokak_kriz k),
 'kaynaklar',coalesce((select jsonb_agg(q) from (select 'oyuncu' tur,null::bigint id,'Kendi cüzdanım' ad union all select 'parti',id,ad from oyun.partiler where gb=u and not kapali union all select 'dernek',id,ad from oyun.dernekler where baskan=u and not kapali) q),'[]'::jsonb),
 'iller',(select jsonb_agg(jsonb_build_object('id',id,'ad',ad,'memnuniyetsizlik',oyun.sokak_memnuniyetsizlik(id)) order by ad) from oyun.iller),
 'eylemler',coalesce((select jsonb_agg(to_jsonb(e)||jsonb_build_object('parti',pa.ad,'il',i.ad,'durum',case when e.durum='aktif' and e.bitis<=t then 'bitti' else e.durum end,'memnuniyetsizlik',oyun.sokak_memnuniyetsizlik(e.il_id),'katilim',(select count(*) from oyun.sokak_eylem_destek d where d.eylem_id=e.id and d.destekci_tur='oyuncu' and d.destek_turu='katilim' and d.taraf='muhalefet'),'destekler',coalesce((select jsonb_agg(jsonb_build_object('tur',d.destekci_tur,'taraf',d.taraf,'tutar',d.tutar,'ad',case when d.destekci_tur='oyuncu' then oyun.kad(d.temsilci) when d.destekci_tur='parti' then (select ad from oyun.partiler where id::text=d.destekci_id) else (select ad from oyun.dernekler where id::text=d.destekci_id) end)) from oyun.sokak_eylem_destek d where d.eylem_id=e.id),'[]'::jsonb)) order by e.baslangic desc) from (select * from oyun.sokak_eylem order by baslangic desc limit 60)e join oyun.partiler pa on pa.id=e.parti_id join oyun.iller i on i.id=e.il_id),'[]'::jsonb));
end $$;

-- RLS: istemci tablolara erişmez, yetki denetimli RPC'leri kullanır.
do $$ declare r text; f record; begin
 foreach r in array array['sokak_eylem_ayar','sokak_eylem','sokak_eylem_fon','sokak_eylem_destek','sokak_kriz'] loop
  execute format('alter table oyun.%I enable row level security',r);
  execute format('revoke all on oyun.%I from public,anon,authenticated',r);
 end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('oyun','public') and p.proname like 'sokak_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);
 end loop;
end $$;
grant execute on function public.sokak_eylemler(),public.sokak_eylem_baslat(integer,text),public.sokak_destek(bigint,text,text,bigint,numeric),public.sokak_yanit(bigint,text) to authenticated;
-- Açılış ayrı, testler tamamlandıktan sonra. Yeniden kurulum aktif ayarını değiştirmez.
update oyun.sokak_eylem_ayar set il_es_zamanli_ust_sinir=1,ulke_es_zamanli_ust_sinir=6,orgut_es_zamanli_destek_siniri=3 where id=1;
-- Gerçekleşmiş borsa işlemleri değiştirilmez: kriz, şirketin kâr beklentisi değerini en fazla %6 azaltır.
create or replace function oyun.sokak_piyasa_riski() returns numeric language sql stable set search_path='' as $$
 select case when coalesce((select aktif from oyun.sokak_eylem_ayar where id=1),false) then least(0.06,count(*)*0.01) else 0 end from oyun.sokak_eylem where durum='aktif' and bitis>oyun.simdi() and kirmizi_baslangic is not null
$$;
create or replace function oyun.sirket_deger(p_sirket bigint) returns numeric language sql stable set search_path='' as $$
 select round(greatest(d*0.5,d+case when k>0 then k*10*(1-oyun.sokak_piyasa_riski()) else k*3 end)) from (select oyun.sirket_defter(p_sirket) d,oyun.sirket_kar7(p_sirket) k)x
$$;
revoke all on function oyun.sokak_piyasa_riski() from public,anon,authenticated;
